# =========================================================================================
# KPI helper — gradient card, native white title, comparative delta vs a baseline column.
# =========================================================================================
def kpi(elid, src, icon, title, valf, fmt, compf, g, trend=None,
        good=TEAL, bad=CORAL, rowband="5 / 13", sub=None):
    cid = f"c-{elid}"
    cont = {"id": cid, "kind": "container", "style": {"borderRadius": "round"},
            "backgroundImage": {"url": g, "style": {"fit": "cover"}}}
    ikn = {"id": f"i-{elid}", "kind": "image", "url": icon, "style": {"fit": "contain"}}
    cols = [{"id": f"k-{elid}v", "formula": valf, "name": title, "format": fmt}]
    kv = {"id": f"k-{elid}", "kind": "kpi-chart", "source": {"elementId": src, "kind": "table"},
          "value": {"columnId": f"k-{elid}v", "color": W, "fontSize": 30},
          "name": {"text": title, "fontSize": 13, "color": W}, "layout": {"anchor": "middle"},
          "style": {"backgroundColor": "transparent", "padding": "none"}}
    if compf:
        cols.append({"id": f"k-{elid}c", "formula": compf, "name": "Baseline", "format": fmt})
        kv["comparisonColumn"] = {"columnId": f"k-{elid}c"}
        kv["comparison"] = {"display": "delta", "colorGood": good, "colorBad": bad, "fontSize": 13}
    kv["columns"] = cols
    els = [cont, ikn, kv]
    if trend:
        ln = {"id": f"ln-{elid}", "kind": "line-chart", "source": {"elementId": src, "kind": "table"},
              "columns": [{"id": f"ln-{elid}m", "formula": f"[{PF}/Month]", "name": "Month", "format": DT},
                          {"id": f"ln-{elid}v", "formula": trend, "name": "Trend"}],
              "xAxis": {"columnId": f"ln-{elid}m", "format": {"marks": "none", "labels": "hidden"}},
              "yAxis": {"columnIds": [f"ln-{elid}v"], "format": {"labels": "hidden", "marks": "none",
                        "scale": {"type": "linear", "zero": False, "hideZeroLine": True}}},
              "name": {"visibility": "hidden"}, "legend": {"visibility": "hidden"},
              "lineAreaStyle": {"interpolation": "monotone"},
              "style": {"backgroundColor": "transparent", "padding": "none"}}
        els.append(ln)
        lay = (f'  <GridContainer elementId="{cid}" type="grid" gridColumn="{{col}}" gridRow="{rowband}" '
               f'gridTemplateColumns="repeat(12, 1fr)" gridTemplateRows="repeat(12,1fr)">\n'
               f'    <LayoutElement elementId="i-{elid}" gridColumn="1 / 3" gridRow="1 / 3"/>\n'
               f'    <LayoutElement elementId="k-{elid}" gridColumn="1 / 13" gridRow="3 / 9"/>\n'
               f'    <LayoutElement elementId="ln-{elid}" gridColumn="1 / 13" gridRow="9 / 12"/>\n  </GridContainer>')
    else:
        lay = (f'  <GridContainer elementId="{cid}" type="grid" gridColumn="{{col}}" gridRow="{rowband}" '
               f'gridTemplateColumns="repeat(12, 1fr)" gridTemplateRows="repeat(12,1fr)">\n'
               f'    <LayoutElement elementId="i-{elid}" gridColumn="1 / 3" gridRow="1 / 3"/>\n'
               f'    <LayoutElement elementId="k-{elid}" gridColumn="1 / 13" gridRow="3 / 11"/>\n  </GridContainer>')
    return els, lay

def header(sfx, title, subtitle):
    c = {"id": f"c-hdr{sfx}", "kind": "container",
         "style": {"borderRadius": "round"}, "backgroundImage": {"url": HEROBG, "style": {"fit": "cover"}}}
    lg = {"id": f"logo{sfx}", "kind": "image", "url": LOGO_WHITE, "style": {"fit": "contain"}}
    tt = {"id": f"ttl{sfx}", "kind": "image", "url": _title_img(title, subtitle), "style": {"fit": "contain"}}
    lay = (f'  <GridContainer elementId="c-hdr{sfx}" type="grid" gridColumn="1 / 25" gridRow="1 / 5" '
           f'gridTemplateColumns="repeat(24, 1fr)" gridTemplateRows="repeat(6,1fr)">\n'
           f'    <LayoutElement elementId="logo{sfx}" gridColumn="2 / 8" gridRow="2 / 5"/>\n'
           f'    <LayoutElement elementId="ttl{sfx}" gridColumn="9 / 23" gridRow="2 / 5"/>\n  </GridContainer>')
    return [c, lg, tt], lay

def _xml(s): return s.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;")
def _title_img(title, subtitle):
    svg = (f'<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 720 120">'
           f'<text x="0" y="52" font-family="Inter,Arial,sans-serif" font-weight="800" font-size="40" '
           f'fill="#FFFFFF">{_xml(title)}</text>'
           f'<text x="2" y="90" font-family="Inter,Arial,sans-serif" font-weight="400" font-size="22" '
           f'fill="#C7D6EC">{_xml(subtitle)}</text></svg>')
    return "data:image/svg+xml;base64," + b64(svg)

