def build(mode):
    wa = mode != "none"
    p1e, p1l = page1(wa); p2e, p2l = page2(wa)
    s = {"name": "Pacific Life — Brand Sponsorship Scorecard", "folderId": FOLDER, "schemaVersion": 1,
         "pages": [{"id": "pg1", "name": "Aggregate Scorecard", "elements": p1e},
                   {"id": "pg2", "name": "Request & Approval", "elements": p2e},
                   requestModal, decisionModal],
         "layout": '<?xml version="1.0" encoding="utf-8"?>\n' + p1l + p2l + requestModal_lay + decisionModal_lay,
         "themeOverrides": theme}
    if wa:
        s["agents"] = [AG_ANALYST, ag_copilot(mode == "tool")]
    return s

def qa(s):
    def _walk(o):
        if isinstance(o, dict):
            for v in o.values(): yield from _walk(v)
        elif isinstance(o, list):
            for v in o: yield from _walk(v)
        elif isinstance(o, str): yield o
    bad = 0
    for x in _walk(s):
        if x.startswith("data:image/svg+xml;base64,"):
            try: _MD.parseString(base64.b64decode(x.split(",", 1)[1]))
            except Exception as e: bad += 1; print("INVALID SVG:", str(e)[:120])
    return bad

def post(s):
    r = urllib.request.Request(BASE + "/v2/workbooks/spec", data=json.dumps(s).encode(), headers=H, method="POST")
    resp = urllib.request.urlopen(r, timeout=120).read().decode()
    wid = [l.split()[-1] for l in resp.splitlines() if "workbookId" in l]
    url = None
    if wid:
        url = json.loads(urllib.request.urlopen(urllib.request.Request(
            BASE + f"/v2/workbooks/{wid[0]}", headers=H), timeout=30).read().decode()).get("url")
    return ("success: true" in resp), url, resp, (wid[0] if wid else None)

if __name__ == "__main__":
    done = False
    for mode in ["tool", "basic", "none"]:
        spec = build(mode)
        if qa(spec): print("ABORT malformed SVG"); sys.exit(1)
        try:
            ok, url, resp, wid = post(spec)
            print(f"POST (agent mode={mode}):", "ACCEPTED" if ok else resp[:400])
            if ok: print("workbookId:", wid); print("URL:", url); done = True; break
        except urllib.error.HTTPError as e:
            raw = e.read().decode()
            try: msg = json.loads(raw).get("message", "")
            except Exception: msg = raw
            print(f"  mode={mode} failed: {e.code} {msg[:300]}")
    if not done: print("ALL MODES FAILED")
